// Display-only identity hiding: raw downloaded data and backup remain intact.
export function identityVisible(s,state={}){return !s.blind||s.blind.revealed===true||state.finished===true;}
export function relativeDay(s,value){const date=String(value??'').slice(0,10),bars=[...(s.history??[]),...s.rounds.map(r=>r.bar).filter(Boolean)],start=(s.history??[]).length;let i=bars.findIndex(b=>b.date===date);if(i>=0)return i<start?`暖機第 ${i-start} 日`:`第 ${i-start+1} 交易日`;if(date<(bars[0]?.date??s.startDate))return '暖機前發布';i=bars.findLastIndex(b=>b.date<=date);return i<start?`暖機第 ${i-start} 日後`:`第 ${i-start+1} 交易日後`;}
export function blindText(value,s){return String(value??'').replaceAll(String(s.asset??'0050 元大台灣50'),'標的 A').replace(/0050|元大台灣\s*50|元大台灣五十|元大臺灣\s*50/gi,'標的 A').replace(/https?:\/\/\S+/gi,'[原始連結待揭露]').replace(/\b(?:JANUARY|FEBRUARY|MARCH|APRIL|MAY|JUNE|JULY|AUGUST|SEPTEMBER|OCTOBER|NOVEMBER|DECEMBER)\s+\d{4}\b/gi,'該統計月份').replace(/\b(?:19|20)\d{2}[-/.年]\d{1,2}(?:[-/.月]\d{1,2}日?)?/g,'[日期隱藏]').replace(/\b(?:19|20)\d{2}\s*年/g,'該年').replace(/\d{1,2}\s*月\s*\d{1,2}\s*日/g,'該日');}
export function newsView(s,state,n){if(identityVisible(s,state))return n;return {title:blindText(n.title,s),body:blindText(n.body,s),source:'官方精選發布（原始連結於揭露後提供）',availableAt:relativeDay(s,n.availableAt??n.publishedAt),publishedAt:relativeDay(s,n.publishedAt??n.availableAt),vintageNote:blindText(n.vintageNote,s),vintageCaveats:n.vintageCaveats?.length?['註記']:[],timestampPrecision:n.timestampPrecision};}
